using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Diagnostics;
using HakutaiKagami.Core.Contracts;
public partial class LandSurveyCheck:Node
{
 async Task Frame()=>await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
 async Task Until(Func<bool> done,string label){var t=Stopwatch.StartNew();while(!done()){if(t.Elapsed.TotalSeconds>300)throw new TimeoutException(label);await Frame();}}
 static void Check(bool condition,string text){if(!condition)throw new InvalidDataException(text);}
 public override async void _Ready(){try{string output=RecordPath.Globalize("res://../Docs/Design/LandSurveyV1/runtime-local/ui");Directory.CreateDirectory(output);var entry=new NewGameFrontEnd();AddChild(entry);await Frame();var start=entry.CreateJudgmentReview(Path.Combine(Path.GetTempPath(),"craft-ui-"+Guid.NewGuid().ToString("N")));entry.QueueFree();await Frame();var game=new NewGameRuntime();game.Configure(start.Store,start.Profile,false);AddChild(game);game.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);await Frame();await Until(()=>!game.IsSaving,"開始保存");
 game.Press("land-survey");await Frame();game.ReviewSurveyPress("measure");await Frame();var job=game.Session.DiagnosticSnapshot().Surveys!.Entries.Single(e=>e.Actor==game.Session.PlayerControl&&e.Input.Action==SurveyAction.Measurement);game.ReviewSocialClose();game.Advance(3*86400);game.ReviewFraction(0);game.Press("save");await Until(()=>!game.IsSaving,"検地途中の保存");var mid=ContractJson.Write(game.Session.DiagnosticSnapshot());string midPose=game.Pose();game.Press("load");await Frame();game.ReviewFraction(0);Check(mid.SequenceEqual(ContractJson.Write(game.Session.DiagnosticSnapshot())),"検地途中の世界一致");Check(midPose==game.Pose(),"検地途中の3D一致");game.Advance(7*86400);game.Press("land-survey");await Frame();game.ReviewSurveyPress("read-"+job.Input.Id.Value);await Frame();Check(LandSurvey.KnownBooks(game.Session.DiagnosticSnapshot(),game.Session.PlayerControl).Any(b=>b.Job==job.Input.Id),"現地で帳面を確認");game.ReviewSurveyPress("tax-Gentle");await Frame();if(DisplayServer.GetName()!="headless"){await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);Check(ViewportCapture.Save(GetViewport(),Path.Combine(output,"survey.png"))==Error.Ok,"検地の自前描画");}game.ReviewSocialClose();game.Advance(14*86400);Check(LandSurvey.EffectiveDecree(game.Session.DiagnosticSnapshot(),job.Input.Site,game.Session.Seconds)?.Input.Rate==LandTaxRate.Gentle,"将来の布告が発効");game.ReviewFraction(0);game.Press("save");await Until(()=>!game.IsSaving,"布告後の保存");var bytes=ContractJson.Write(game.Session.DiagnosticSnapshot());string pose=game.Pose();game.Press("load");await Frame();game.ReviewFraction(0);Check(bytes.SequenceEqual(ContractJson.Write(game.Session.DiagnosticSnapshot())),"布告後の世界一致");Check(pose==game.Pose(),"3D一致");File.WriteAllText(Path.Combine(output,"before-pose.json"),pose);File.WriteAllText(Path.Combine(output,"restored-pose.json"),game.Pose());File.WriteAllText(Path.Combine(output,"result.json"),System.Text.Json.JsonSerializer.Serialize(new{Status="PASSED",Scope="通常開始・検地・現地帳面・年貢布告・途中保存復旧",ComputerUse="未使用"}));GD.Print("LAND_SURVEY_UI_PASS");game.QueueFree();await Frame();GetTree().Quit();}catch(Exception e){GD.PrintErr(e);GetTree().Quit(1);}}
}
